script:
// =====================================================================
//  LED panel – interaktív huzalozási rajz (előlnézet + LED panel)
//  FEHÉR LED-ek, exponenciális (Shockley-típusú) karakterisztikával.
//  A kapcsolási rajz szerint:
//   • 1A (+12 V) → K1 → A1 → A2 → R3 + LED4–6 (3 LED sorosan) → C2
//   • 1A–P1–1B  potméter feszültségosztó, a csúszka → K2 → B1 → B2
//        → R2 + LED2–3 (2 LED sorosan)  és  R1 + LED1 (párhuzamosan)
//   • C2 → C1 → 1B (a LED-ek katódos közös ága a mínuszra megy)
//  Ez huzalozási (realisztikus) rajz, ezért az alkatrészek nem IEC jelek:
//  kerek LED, téglalap alakú ellenállás, kés-kapcsoló, gombos potméter.
// =====================================================================
stage(1000, 600, "#fbfbf8");
title({hu: "LED panel – huzalozási rajz szerint (fehér LED-ek)", en: "LED panel – according to the wiring diagram (white LEDs)"});

param("pot", {hu: "Potméter állása (P1)", en: "Potentiometer position (P1)"}, 0, 100, 80, 1, "%");      // 0 % = 1B (0 V), 100 % = 1A (+12 V)
param("Rp", {hu: "Potméter ellenállása", en: "Potentiometer resistance"}, 100, 10000, 1000, 100, "Ω");
toggle("k1", {hu: "K1 kapcsoló (LED4–6)", en: "Switch K1 (LED4–6)"}, true);
toggle("k2", {hu: "K2 kapcsoló (LED1–3)", en: "Switch K2 (LED1–3)"}, true);
plotWindow(10);

// ---------- állandók ----------
const VS = 12;            // tápfeszültség a banánhüvelyeken (V)
const R1 = 680;           // R1 ellenállása (Ω) – LED1 előtét
const R2 = 520;           // R2 ellenállása (Ω) – LED2–3 előtét
const R3 = 480;           // R3 ellenállása (Ω) – LED4–6 előtét

// Fehér LED modell: u = aLED · ln(1 + i/Is)   (egy LED feszültsége az áram függvényében)
//  • aLED = n·UT ≈ 0,12 V: az áram tízszereződésére kb. 0,28 V feszültségnövekedés jut
//  • Is úgy van megválasztva, hogy 20 mA-nél a nyitófeszültség 3,1 V legyen (tipikus fehér LED);
//    így 1 mA-nél kb. 2,7 V, 5 mA-nél kb. 2,9 V adódik
const aLED = 0.12;                        // karakterisztika meredeksége (V)
const UF20 = 3.1;                         // nyitófeszültség 20 mA-nél (V)
const IS_LED = 0.02 * exp(-UF20 / aLED);  // telítési áram (A)
const IREF = 0.012;       // ennél az áramnál (12 mA) világít teljes fénnyel a rajzolt LED
const kSp = 7000;         // nyilak sebessége: 1 mA = 7 px/s (1 A = 7000 px/s)

// Egy LED feszültsége (V) adott áramnál (A)
function uLED(I) { return aLED * log(1 + max(I, 0) / IS_LED); }

// ---------- fizika: egy ág árama ----------
// Egy ág: n db fehér LED sorosan + R ellenállás, az ágra U feszültség jut.
// Megoldjuk:  n·aLED·ln(1 + i/Is) + i·R = U   (a bal oldal i-ben szigorúan nő → felezéses keresés)
// Ha U kisebb, mint a LED-ek nyitófeszültsége, az áram gyakorlatilag 0 (a LED nem világít).
function iString(U, n, R) {
  if (U <= 0) return 0;
  let lo = 0, hi = U / R;                       // az áram 0 és U/R között van
  for (let k = 0; k < 40; k++) {
    const mid = (lo + hi) / 2;
    const f = n * uLED(mid) + mid * R - U;
    if (f > 0) hi = mid; else lo = mid;
  }
  return (lo + hi) / 2;
}

// ---------- fizika: az egész áramkör (a csúszkák értékéből) ----------
function solve() {
  const x = P.pot / 100;                        // csúszka helyzete 0…1 (1B-től 1A felé)
  const Rup = max(P.Rp * (1 - x), 0.5);         // a potméter felső része (1A és csúszka között) – ez van sorban a LED-ekkel
  const Rlo = max(P.Rp * x, 0.5);               // a potméter alsó része (csúszka és 1B között) – ez párhuzamos a LED-ágakkal
  // A ág: K1 közvetlenül a 12 V-ra köti a LED4–6 + R3 ágat
  const IA = P.k1 ? iString(VS, 3, R3) : 0;
  // B ág: a csúszka feszültsége (Ub) terheli a LED1 és a LED2–3 ágat (K2 zárva)
  // Csomóponti egyenlet a csúszkánál: (VS−Ub)/Rup = Ub/Rlo + I1(Ub) + I23(Ub) – felezéssel oldjuk meg
  let lo = 0, hi = VS;
  for (let k = 0; k < 40; k++) {
    const Ub = (lo + hi) / 2;
    const load = P.k2 ? iString(Ub, 1, R1) + iString(Ub, 2, R2) : 0;
    const g = (VS - Ub) / Rup - Ub / Rlo - load;   // g > 0 → Ub még nőhet
    if (g > 0) lo = Ub; else hi = Ub;
  }
  const Ub = (lo + hi) / 2;
  const I1 = P.k2 ? iString(Ub, 1, R1) : 0;
  const I23 = P.k2 ? iString(Ub, 2, R2) : 0;
  return {Ub, IA, I1, I23, IB: I1 + I23, Iup: (VS - Ub) / Rup, Ilo: Ub / Rlo};
}
// A vezetékszakaszokon folyó áramok (A) – a mozgó nyilak ezekből készülnek
function groups(s) {
  return {Is: s.IA + s.Iup, IA: s.IA, IB: s.IB, IC: s.IA + s.IB, Iup: s.Iup, Ilo: s.Ilo,
          I1: s.I1, I23: s.I23, IAI23: s.IA + s.I23};
}

// A nyilak eltolása (px) szakaszcsoportonként; update-ben integráljuk, hogy ne ugráljanak
const pos = {Is: 0, IA: 0, IB: 0, IC: 0, Iup: 0, Ilo: 0, I1: 0, I23: 0, IAI23: 0};
update(dt => {
  const g = groups(solve());
  for (const k in pos) pos[k] += kSp * g[k] * dt;
});

// ---------- geometria ----------
// LED soron belüli vezetékdarabok: az alkatrészek (LED, ellenállás) szélén megállnak
function rowSeg(y, xs) {                        // xs: a LED-ek középpontja jobbról balra
  const out = []; let prev = 276;               // 276 = az ellenállás bal széle
  for (const xl of xs) { out.push([[prev, y], [xl + 16, y]]); prev = xl - 16; }
  out.push([[prev, y], [55, y]]);
  return out;
}
// Teljes (fekete) vezetékek – az alkatrészek takarják el, ahol átmennek rajtuk
const WIRES = [
  [[96, 110], [230, 110]], [[310, 110], [360, 110], [360, 130], [420, 130]],   // 1A → K1 → A1
  [[150, 110], [150, 150]], [[310, 165], [420, 165]], [[150, 220], [150, 260]],
  [[96, 260], [350, 260], [350, 200], [420, 200]],                              // 1B – C1
  [[450, 130], [600, 130], [600, 505], [450, 505]],                             // A1 – A2
  [[450, 165], [580, 165], [580, 425], [450, 425]],                             // B1 – B2
  [[450, 350], [560, 350], [560, 200], [450, 200]],                             // C2 – C1
  [[55, 350], [420, 350]], [[55, 350], [55, 505]],                              // közös katódvezeték
  [[55, 400], [380, 400], [380, 450]], [[55, 450], [380, 450]], [[55, 505], [420, 505]], [[420, 425], [380, 425]]
];
// Mozgó áramnyilak: [csoport, útvonal] – útvonal az áram (technikai irány) mentén
const FLOWS = [
  ["Is", [[96, 110], [150, 110]]], ["Is", [[150, 260], [96, 260]]],
  ["IA", [[150, 110], [230, 110]]], ["IA", [[310, 110], [360, 110], [360, 130], [415, 130]]],
  ["IA", [[450, 130], [600, 130], [600, 505], [450, 505]]], ["IA", [[415, 505], [345, 505]]],
  ...rowSeg(505, [235, 165, 95]).map(s => ["IA", s]), ["IA", [[55, 505], [55, 450]]],
  ["Iup", [[150, 110], [150, 148]]], ["Ilo", [[150, 222], [150, 260]]],
  ["IB", [[310, 165], [415, 165]]], ["IB", [[450, 165], [580, 165], [580, 425], [450, 425]]],
  ["IB", [[415, 425], [380, 425]]],
  ["I1", [[380, 425], [380, 400], [345, 400]]], ...rowSeg(400, [165]).map(s => ["I1", s]),
  ["I23", [[380, 425], [380, 450], [345, 450]]], ...rowSeg(450, [210, 120]).map(s => ["I23", s]),
  ["IAI23", [[55, 450], [55, 400]]],
  ["IC", [[55, 400], [55, 350], [415, 350]]], ["IC", [[450, 350], [560, 350], [560, 200], [450, 200]]],
  ["IC", [[415, 200], [350, 200], [350, 260], [155, 260]]]
];

// ---------- rajzoló segédfüggvények ----------
function dot(x, y) { circle(x, y, 4, {fill: C.ink, stroke: null}); }       // vezeték-csomópont

// Fehér LED: az I árammal arányos fényerő. IREF (12 mA) = teljes fény; a 0,7-es kitevő az érzékelést közelíti
function led(x, y, I, name) {
  const b = clamp(pow(I / IREF, 0.7), 0, 1);                               // fényerő 0…1
  if (b > 0.02) for (let k = 3; k >= 1; k--) circle(x, y, 14 + 7 * k * b, {fill: "#ffd84d", stroke: null, alpha: 0.18 * b});   // sárgás fény-udvar
  circle(x, y, 15, {fill: "#e8e8e8", stroke: C.ink, lw: 2});               // műanyag peremes burkolat
  // kikapcsolva sárgás fényporréteg (170,165,130), bekapcsolva fehér (255,255,235)
  circle(x, y, 10, {fill: "rgb(" + round(lerp(170, 255, b)) + "," + round(lerp(165, 255, b)) + "," + round(lerp(130, 235, b)) + ")", stroke: C.gray, lw: 1});
  text(name, x, y - 24, {size: 12, align: "center"});
}
function res(cx, y, name, ohm) {                                           // ellenállás: téglalap
  rect(cx - 30, y - 8, 60, 16, {fill: "#e3cf9f", stroke: C.ink, lw: 2, radius: 5});
  text(name + " " + ohm + " Ω", cx, y - 14, {size: 12, align: "center"});
}
function sw(xa, y, xb, on, name) {                                         // kés-kapcsoló: zárva vízszintes, nyitva felemelt
  rect(xa - 6, y - 20, xb - xa + 12, 40, {fill: "#f4f4f4", stroke: C.gray, lw: 1.5, radius: 8});
  line(xa, y, on ? xb : xb - 8, on ? y : y - 30, {stroke: C.ink, lw: 5});
  circle(xa, y, 5, {fill: C.ink, stroke: null}); circle(xb, y, 5, {fill: C.ink, stroke: null});
  text(name, xa - 6, y - 26, {size: 15, bold: true});
}
function block(y0, h, rowsY, labels) {                                     // sorkapocs: bal oszlop = panel, jobb = kábel
  rect(405, y0, 60, h, {fill: "#f2f2ee", stroke: C.gray, lw: 2, radius: 4});
  for (let k = 0; k < rowsY.length; k++) {
    line(420, rowsY[k], 450, rowsY[k], {stroke: C.gray, lw: 4});
    circle(420, rowsY[k], 5, {fill: "#999", stroke: C.ink, lw: 1});
    circle(450, rowsY[k], 5, {fill: "#999", stroke: C.ink, lw: 1});
    text(labels[k], 462, rowsY[k] - 6, {size: 12, bold: true});
  }
}
function arrowsOn(g, key, pts) {                                           // áramnyilak; nulla áramnál nem látszanak
  const I = g[key];
  if (I > 2e-5) flow(pts, {pos: pos[key], dir: 1, line: false, color: C.orange, spacing: 30, alpha: clamp(0.35 + I * 1000 / 12, 0, 1)});
}

draw(t => {
  const s = solve(), g = groups(s);
  const x = P.pot / 100;                       // csúszka helyzete 0…1
  const yw = 220 - 70 * x;                     // csúszka y-pozíciója a potméter-ellenálláson (px)

  // 1) panelek
  rect(30, 60, 470, 240, {fill: "#ffffff", stroke: C.ink, lw: 2});
  rect(30, 325, 470, 255, {fill: "#ffffff", stroke: C.ink, lw: 2});
  text({hu: "Elölnézet", en: "Front view"}, 490, 290, {size: 13, bold: true, align: "right"});
  text({hu: "LED panel", en: "LED panel"}, 490, 570, {size: 13, bold: true, align: "right"});

  // 2) vezetékek (feketék), alattuk a csomópontok
  for (const w of WIRES) polyline(w, {stroke: C.ink, lw: 3});
  const wiper = [[170, yw], [190, yw], [190, 165], [230, 165]];            // csúszka → K2
  polyline(wiper, {stroke: C.ink, lw: 3});

  // 3) mozgó áramnyilak (a vezetékdarabokon, alkatrészen át nem mennek)
  for (const f of FLOWS) arrowsOn(g, f[0], f[1]);
  arrowsOn(g, "IB", wiper);

  // 4) alkatrészek (rájuk kerülnek a vezetékekre)
  // banánhüvelyek
  circle(80, 110, 16, {fill: C.red, stroke: C.ink, lw: 2}); circle(80, 110, 8, {fill: "#b02a2a", stroke: null});
  circle(80, 260, 16, {fill: "#333", stroke: C.ink, lw: 2}); circle(80, 260, 8, {fill: "#111", stroke: null});
  text("1A (+12 V)", 80, 84, {size: 14, bold: true, align: "center"});
  text("1B (0 V)", 80, 292, {size: 14, bold: true, align: "center"});
  // potméter: ellenállás-test + gomb (a gomb 270°-ot fordul)
  rect(142, 150, 16, 70, {fill: "#e3cf9f", stroke: C.ink, lw: 2});
  polygon([[158, yw], [170, yw - 6], [170, yw + 6]], {fill: C.ink, stroke: null});  // csúszka nyila
  text("P1", 166, 145, {size: 14, bold: true});
  line(112, 185, 142, 185, {stroke: C.gray, lw: 2, dash: [4, 3]});          // mechanikai kapcsolat (gomb – potméter)
  const a = deg(-135 + 270 * x);                                            // gomb szöge a függőlegestől, óramutató irányában
  circle(80, 185, 32, {fill: "#bdbdbd", stroke: C.ink, lw: 2});
  circle(80, 185, 24, {fill: "#555", stroke: null});
  line(80, 185, 80 + 28 * sin(a), 185 - 28 * cos(a), {stroke: "#fff", lw: 4});
  text(fmt(P.pot, 0) + " %", 80, 235, {size: 13, align: "center", bold: true});
  // kapcsolók
  sw(230, 110, 310, P.k1, "K1");
  sw(230, 165, 310, P.k2, "K2");
  // sorkapcsok
  block(112, 106, [130, 165, 200], ["A1", "B1", "C1"]);
  block(335, 185, [350, 425, 505], ["C2", "B2", "A2"]);
  text({hu: "sorkapocs", en: "terminal block"}, 435, 234, {size: 11, align: "center", color: C.gray});
  text({hu: "sorkapocs", en: "terminal block"}, 435, 536, {size: 11, align: "center", color: C.gray});
  // csomópontok
  for (const p of [[150, 110], [150, 260], [55, 400], [55, 450], [380, 425]]) dot(p[0], p[1]);
  // ellenállások és LED-ek a panelen
  res(310, 400, "R1", R1); res(310, 450, "R2", R2); res(310, 505, "R3", R3);
  led(165, 400, s.I1, "LED1");
  led(210, 450, s.I23, "LED3"); led(120, 450, s.I23, "LED2");
  led(235, 505, s.IA, "LED6"); led(165, 505, s.IA, "LED5"); led(95, 505, s.IA, "LED4");

  // 5) mérőműszer-rész a jobb oldalon
  const bx = 660;
  text({hu: "Ágak árama és LED-feszültsége", en: "Branch currents and LED voltages"}, bx, 100, {size: 18, bold: true});
  const names = [{hu: "LED4–6 + R3 (A ág, K1)", en: "LED4–6 + R3 (branch A, K1)"},
                 {hu: "LED2–3 + R2 (B ág, K2)", en: "LED2–3 + R2 (branch B, K2)"},
                 {hu: "LED1 + R1 (B ág, K2)", en: "LED1 + R1 (branch B, K2)"}];
  const cur = [s.IA, s.I23, s.I1];
  for (let k = 0; k < 3; k++) {
    const y0 = 130 + k * 62;
    text(names[k], bx, y0, {size: 14});
    rect(bx, y0 + 8, 300, 16, {fill: "#eeeeea", stroke: C.gray, lw: 1});
    rect(bx, y0 + 8, 300 * clamp(cur[k] / 0.02, 0, 1), 16, {fill: C.orange, stroke: null});   // 20 mA = teli sáv
    text(fmt(cur[k] * 1000, 1) + " mA   |   " + fmt(uLED(cur[k]), 2) + " V / LED", bx, y0 + 44, {size: 14, bold: true});
  }
  text({hu: "A csúszka feszültsége U_B", en: "Wiper voltage U_B"}, bx, 345, {size: 14});
  rect(bx, 353, 300, 16, {fill: "#eeeeea", stroke: C.gray, lw: 1});
  rect(bx, 353, 300 * s.Ub / VS, 16, {fill: C.blue, stroke: null});                          // 12 V = teli sáv
  text(fmt(s.Ub, 2) + " V", bx, 389, {size: 14, bold: true});
  text({hu: "Tápegység árama: ", en: "Supply current: "}, bx, 430, {size: 14});
  text(fmt((s.IA + s.Iup) * 1000, 1) + " mA", bx + 190, 430, {size: 14, bold: true});
  // A LED-ágakkal sorba kötött potméter-rész: 1A és a csúszka között (R_fel = Rp·(1−x))
  text({hu: "Sorba kötött potméter-rész: ", en: "Series pot. part: "}, bx, 455, {size: 14});
  text(fmt(P.Rp * (1 - x), 0) + " Ω", bx + 190, 455, {size: 14, bold: true, color: C.purple});
  // A LED-ágakkal párhuzamos rész: a csúszka és 1B között (R_le = Rp·x)
  text({hu: "Párhuzamos potméter-rész: ", en: "Parallel pot. part: "}, bx, 478, {size: 14});
  text(fmt(P.Rp * x, 0) + " Ω", bx + 190, 478, {size: 14, bold: true, color: C.gray});
  text({hu: "A potméter csak a B ágat (K2) szabályozza;\nA K1 ág közvetlenül a 12 V-ot kapja.",
        en: "The potentiometer controls only branch B (K2);\nthe K1 branch is fed directly from 12 V."},
       bx, 520, {size: 13, color: C.gray});

  // 6) kijelzők és grafikonok
  show({hu: "Csúszka feszültsége U_B", en: "Wiper voltage U_B"}, s.Ub, "V", 2);
  show({hu: "LED4–6 árama (A ág)", en: "LED4–6 current (branch A)"}, s.IA * 1000, "mA", 1);
  show({hu: "Egy LED feszültsége a LED4–6 ágban", en: "Voltage of one LED in LED4–6 branch"}, uLED(s.IA), "V", 2);
  show({hu: "LED2–3 árama", en: "LED2–3 current"}, s.I23 * 1000, "mA", 1);
  show({hu: "Egy LED feszültsége a LED2–3 ágban", en: "Voltage of one LED in LED2–3 branch"}, uLED(s.I23), "V", 2);
  show({hu: "LED1 árama", en: "LED1 current"}, s.I1 * 1000, "mA", 1);
  show({hu: "LED1 feszültsége", en: "LED1 voltage"}, uLED(s.I1), "V", 2);
  show({hu: "Sorba kötött potméter-rész R_fel (1A–csúszka)", en: "Series pot. part R_up (1A–wiper)"}, P.Rp * (1 - x), "Ω", 0);
  show({hu: "Párhuzamos potméter-rész R_le (csúszka–1B)", en: "Parallel pot. part R_low (wiper–1B)"}, P.Rp * x, "Ω", 0);
  show({hu: "Tápegység árama", en: "Supply current"}, (s.IA + s.Iup) * 1000, "mA", 1);
  plot({hu: "LED4–6 árama", en: "LED4–6 current"}, s.IA * 1000, {unit: "mA", color: C.red, min: 0, group: "I"});
  plot({hu: "LED2–3 árama", en: "LED2–3 current"}, s.I23 * 1000, {unit: "mA", color: C.orange, min: 0, group: "I"});
  plot({hu: "LED1 árama", en: "LED1 current"}, s.I1 * 1000, {unit: "mA", color: C.purple, min: 0, group: "I"});
  plot("U_B", s.Ub, {unit: "V", color: C.blue, min: 0, max: 12, group: "U"});
  val({Ub: s.Ub, IA: s.IA, I1: s.I1, I23: s.I23});
});
